-- DB-05: qualified exact-current audit19 cleanup; independent live issuer/source/purpose qualification remains required.
BEGIN;
-- DB05_INSTALL_OWNER_SCOPE_BEGIN
-- Same guarded atomic install capability as existing OPS part03/part11.
-- No role/owner/application capability persists outside this transaction.
DO $db05_install_preflight$
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres'
 OR NOT EXISTS(SELECT FROM pg_roles WHERE rolname='postgres' AND NOT rolsuper AND rolinherit AND rolcreaterole AND rolbypassrls)
 OR NOT EXISTS(SELECT FROM pg_roles WHERE rolname='gridex_ediel_retention_owner' AND NOT rolcanlogin AND NOT rolinherit AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND rolbypassrls)
 OR (SELECT nspowner FROM pg_namespace WHERE nspname='gridex_ediel_retention') IS DISTINCT FROM 'gridex_ediel_retention_owner'::regrole::oid
 OR EXISTS(SELECT FROM pg_auth_members WHERE roleid='gridex_ediel_retention_owner'::regrole AND member<>'postgres'::regrole)
 OR (SELECT jsonb_agg(jsonb_build_array(g.rolname,m.admin_option,m.inherit_option,m.set_option) ORDER BY g.rolname COLLATE "C") FROM pg_auth_members m JOIN pg_roles g ON g.oid=m.grantor WHERE m.roleid='gridex_ediel_retention_owner'::regrole AND m.member='postgres'::regrole)
 IS DISTINCT FROM '[["postgres",false,false,true],["supabase_admin",true,false,false]]'::jsonb
 OR pg_has_role('postgres','gridex_ediel_retention_owner','USAGE') IS DISTINCT FROM false
 OR pg_has_role('postgres','gridex_ediel_retention_owner','SET') IS DISTINCT FROM true
 OR pg_has_role('postgres','gridex_ediel_retention_owner','MEMBER') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'db05_qualified_non_super_migration_owner_profile_required' USING ERRCODE='42501';END IF;
 IF to_regclass('pg_temp.gridex_db05_install_scope') IS NOT NULL THEN RAISE EXCEPTION 'db05_unexpected_existing_install_scope';END IF;
END $db05_install_preflight$;
CREATE TEMPORARY TABLE gridex_db05_install_scope ON COMMIT DROP AS
 SELECT (SELECT jsonb_agg(to_jsonb(m) ORDER BY m.oid) FROM pg_auth_members m) AS memberships,
 (SELECT jsonb_agg(to_jsonb(r)-'rolpassword' ORDER BY r.oid) FROM pg_roles r) AS roles,
 (SELECT jsonb_agg(to_jsonb(n) ORDER BY n.oid) FROM pg_namespace n WHERE n.nspname IN('public','gridex_ediel_retention')) AS namespaces,
 has_schema_privilege('gridex_ediel_retention_owner','public','CREATE') AS owner_public_create;
GRANT gridex_ediel_retention_owner TO postgres WITH ADMIN FALSE, INHERIT TRUE, SET TRUE GRANTED BY postgres;
DO $db05_install_capability$ BEGIN
 IF NOT pg_has_role('postgres','gridex_ediel_retention_owner','USAGE') THEN RAISE EXCEPTION 'db05_atomic_owner_inheritance_unavailable';END IF;
 IF NOT has_schema_privilege('gridex_ediel_retention_owner','public','CREATE') THEN GRANT CREATE ON SCHEMA public TO gridex_ediel_retention_owner;END IF;
END $db05_install_capability$;
-- DB05_INSTALL_OWNER_SCOPE_END

CREATE TABLE gridex_ediel_retention.audit19_approvals_v1(
 company_id uuid NOT NULL REFERENCES public.companies(id),target_audit_id uuid NOT NULL,
 source_commitment text NOT NULL,receipt jsonb NOT NULL,receipt_hash text NOT NULL,
 reviewer_user_id uuid NOT NULL REFERENCES auth.users(id),approved_at timestamptz NOT NULL,
 execution_actor_id uuid NOT NULL REFERENCES auth.users(id),expires_at timestamptz NOT NULL,
 PRIMARY KEY(company_id,target_audit_id),CHECK(isfinite(approved_at) AND isfinite(expires_at) AND expires_at>approved_at),CHECK(reviewer_user_id<>execution_actor_id));
CREATE TABLE gridex_ediel_retention.audit19_permits_v1(
 backend integer NOT NULL,xid bigint NOT NULL,relation oid NOT NULL,company_id uuid NOT NULL,target_id uuid NOT NULL,
 operation text NOT NULL,old_hash text,new_hash text,PRIMARY KEY(backend,xid,relation,company_id,target_id,operation));
ALTER TABLE gridex_ediel_retention.audit19_approvals_v1 OWNER TO gridex_ediel_retention_owner;
ALTER TABLE gridex_ediel_retention.audit19_permits_v1 OWNER TO gridex_ediel_retention_owner;
REVOKE ALL ON gridex_ediel_retention.audit19_approvals_v1,gridex_ediel_retention.audit19_permits_v1 FROM PUBLIC,anon,authenticated,service_role;
-- Deliberate new owner rights, never inferred from old INSERT/audit.log rights.
GRANT SELECT,DELETE ON public.audit_logs TO gridex_ediel_retention_owner;
-- PostgreSQL row locks require a column UPDATE grant; no UPDATE port is exposed.
GRANT UPDATE(id) ON public.audit_logs TO gridex_ediel_retention_owner;
INSERT INTO public.permissions(key,name,description,category,is_active)
 SELECT 'ediel.retention.audit_normalized19_cleanup','Qualified audit19 cleanup','Exact signed audit19 cleanup only','ediel_retention',true
 WHERE NOT EXISTS(SELECT FROM public.permissions WHERE key='ediel.retention.audit_normalized19_cleanup');
INSERT INTO gridex_ediel_retention.decision_evidence_catalog VALUES('audit_normalized19_cleanup','public.audit_logs','ediel.retention.audit_normalized19_cleanup','audit19_approvals_v1','target_audit_id','audit19_receipt_v1');
-- No role/user/default class grant is created.
CREATE FUNCTION gridex_ediel_retention.audit19_schema_v1() RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid='public.audit_logs'::regclass AND attnum>0 AND NOT attisdropped)
 IS DISTINCT FROM ARRAY['id','company_id','actor_user_id','entity_type','entity_id','action','old_values','new_values','metadata','created_at','updated_at','actor_type','system_actor','request_id','correlation_id','resource_type','resource_id','previous_status','new_status']
 OR (SELECT array_agg(atttypid::regtype::text ORDER BY attnum) FROM pg_attribute WHERE attrelid='public.audit_logs'::regclass AND attnum>0 AND NOT attisdropped)
 IS DISTINCT FROM ARRAY['uuid','uuid','uuid','text','text','text','jsonb','jsonb','jsonb','timestamp with time zone','timestamp with time zone','text','text','text','text','text','text','text','text'] THEN RAISE EXCEPTION 'audit19_exact_schema_required' USING ERRCODE='42501';END IF;
END$$;
CREATE FUNCTION gridex_ediel_retention.audit19_hash_v1(a public.audit_logs) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM gridex_ediel_retention.audit19_schema_v1();
 RETURN encode(sha256(convert_to('audit19_canonical_utc_v1:'||((to_jsonb(a)-ARRAY['created_at','updated_at'])||jsonb_build_object('created_at',to_char(a.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char(a.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))::text,'UTF8')),'hex');END$$;
CREATE FUNCTION gridex_ediel_retention.audit19_a_hash_v1(a gridex_ediel_retention.audit19_approvals_v1) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid='gridex_ediel_retention.audit19_approvals_v1'::regclass AND attnum>0 AND NOT attisdropped) IS DISTINCT FROM ARRAY['company_id','target_audit_id','source_commitment','receipt','receipt_hash','reviewer_user_id','approved_at','execution_actor_id','expires_at'] THEN RAISE EXCEPTION 'audit19_exact_A9_required' USING ERRCODE='42501';END IF;
 RETURN encode(sha256(convert_to('audit19_A9_utc_v1:'||((to_jsonb(a)-ARRAY['approved_at','expires_at'])||jsonb_build_object('approved_at',to_char(a.approved_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(a.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))::text,'UTF8')),'hex');END$$;
